\]
was added to the primary MSE loss. The overall loss was defined as
\[
L = L_{p} + \lambda L_{aux},
\]
where \(L_{p}\) is the primary loss and \(\lambda\) is a weighting parameter that balances the influence of the auxiliary loss.

A custom training procedure (see Algorithm~\ref{alg:train_variant}) was implemented for each model variant:

\begin{algorithm}[H]
\caption{Training Procedure for a Model Variant}\label{alg:train_variant}
\begin{algorithmic}[1]
\State \textbf{Input:} {Dataset \(D = \{(x_i, \alpha_i, m_i)\}\), learning rate \(\eta\), number of epochs \(T\)}
\For{epoch \(= 1, \dots, T\)}
    \For{each sample \((x, \alpha, m) \in D\)}
        \State Compute embeddings \(e \gets \texttt{extract\_embeddings}(x)\)
        \State Predict output \(y, \hat{m} \gets \texttt{model}(e, \alpha)\)
        \State Compute primary loss \(L_p \gets \|y - 0\|^2\)
        \State Compute auxiliary loss \(L_{aux} \gets \|\hat{m} - m\|^2\)
        \State Set total loss \(L \gets L_p + \lambda L_{aux}\)
        \State Update model parameters using gradient descent with learning rate \(\eta\)
    \EndFor
\EndFor
\end{algorithmic}
\end{algorithm}

